{
  "failure_mode": "collision",
  "evidence": [
    "c5t18_s1062887440: collision at 62.55 s while robot was stopped, mover_03 at [-0.14, 0.57] m, closing speed 0.66 m/s.",
    "c5t18_s770177675: collision at 9.267 s while robot was stopped, mover_00 at [-0.89, 0.42] m, closing speed 0.42 m/s.",
    "first_not_on_map shows unmapped object first detected (e.g., 57.55 s, 1.88 m away) but robot still collides later, indicating raw TTC stop missed the object."
  ],
  "assumptions": [
    {
      "assumption": "Moving objects generate at least three lidar points per scan within detection range.",
      "holds": false,
      "why": "Collisions occurred with small boxes that often produced fewer than three points, so _raw_ttc_stop and related checks never triggered."
    },
    {
      "assumption": "A TTC threshold of 1 s is sufficient to stop before any collision given max robot speed 1.5 m/s and mover speed 2 m/s.",
      "holds": false,
      "why": "Robots stopped but were still hit by movers approaching from the side, showing that 1 s TTC does not cover lateral approaches."
    },
    {
      "assumption": "After a pause the robot can safely resume waypoint following without immediate re‑evaluation of nearby movers.",
      "holds": false,
      "why": "In the failure runs the robot resumed motion while a mover was still within the safety envelope, leading to impact."
    },
    {
      "assumption": "VO planner or predictive speed will always produce a safe command when a mover is within _SAFE_DIST.",
      "holds": false,
      "why": "VO and predictive speed failed to generate avoidance when the mover was very close and the robot was stationary."
    }
  ],
  "approach_families": [
    {
      "family": "raw_ttc_stop (early binary pause)",
      "turns": "18",
      "result": "7 attempts, 4 passes"
    },
    {
      "family": "predictive_speed / TTC scaling",
      "turns": "2‑17 (most turns)",
      "result": "≈15 attempts, 9 passes"
    },
    {
      "family": "velocity‑obstacle (VO) planner",
      "turns": "5‑17",
      "result": "≈13 attempts, 27 passes (overall best performer but still misses side collisions)"
    },
    {
      "family": "potential‑field avoidance",
      "turns": "11",
      "result": "7 attempts, 4 passes"
    },
    {
      "family": "dynamic‑window approach (DWA)",
      "turns": "12",
      "result": "5 attempts, 2 passes"
    },
    {
      "family": "vector‑field histogram (VFH)",
      "turns": "13",
      "result": "3 attempts, 0 passes"
    },
    {
      "family": "A* re‑planning with dynamic grid",
      "turns": "16",
      "result": "3 attempts, 0 passes"
    }
  ],
  "candidates": [
    {
      "idea": "Add a continuous danger‑envelope monitor that, when a pause is active, keeps the robot stopped and rotates in place away from any mover still inside a critical radius (e.g., 0.8 m).",
      "new_family": true,
      "for": "collisions while robot is stationary and movers approach from the side",
      "risk": "May increase time‑to‑goal if rot‑ate‑away is over‑used; must ensure rotation does not violate static map."
    },
    {
      "idea": "Implement a simple angular‑sector gap finder each step (sample 5° sectors, pick the widest gap free of unmapped points and tracked movers) and steer toward that gap while still heading to the waypoint.",
      "new_family": true,
      "for": "cases where VFH failed due to coarse binning",
      "risk": "Might produce jerky steering if gap changes rapidly; needs smoothing."
    },
    {
      "idea": "Introduce a Kalman‑filter based track estimator that predicts future mover positions and generates a lateral detour waypoint using linear extrapolation, independent of VO.",
      "new_family": true,
      "for": "improving prediction accuracy for small, fast‑moving boxes",
      "risk": "Adds computational overhead and requires tuning of process noise."
    }
  ],
  "chosen": "Candidate 1 – continuous danger‑envelope monitoring with in‑place rotation, because it directly addresses the observed collisions while the robot is stopped.",
  "target": "controller logic and a new _evade_rotate helper (plus new state flags in st)",
  "direction": "1. After _perceive, compute M and call _raw_ttc_stop as before; if it returns a pause, set st[\"evade_mode\"] = True and st[\"evade_until\"] = t + 0.5. 2. While st[\"evade_mode\"] is True, call a new function _evade_rotate(st, pose, M) that finds the nearest mover inside a critical radius (e.g., 0.8 m) and returns (v=0, w) with w = ±1.0 rad/s to rotate away from the mover. 3. Keep rotating until either no mover is within the critical radius or a timeout (e.g., 3 s) expires, then clear st[\"evade_mode\"] and resume normal waypoint/VO logic. 4. Ensure _evade_rotate checks _map_free and _lidar_clear so the robot does not rotate into a wall. 5. Update _guard to accept zero‑velocity commands from _evade_rotate without overriding them. 6. Reset st[\"pause_until\"] only after evasion completes, preventing premature resumption.",
  "confidence": "medium"
}
